Output4[Expected approach] Using LPS of KMP Algorithm The idea is to use the preprocessing step of the KMP (Knuth-Morris-Pratt) algorithm. In this step, we construct an LPS (Longest Prefix Suffix) array, where each index i stores the length of the longest proper prefix of the substring str[0...i] that is also a suffix of the same substring. The value at the last index of the LPS array represents the length of the longest proper prefix which is also a suffix for the entire string.
            C++

    #include <iostream>
#include <vector>
#include <string>
using namespace std;

int getLPSLength(string& s) {

    int n = s.size();

    // initialize LPS array with 0s
    vector<int> lps(n, 0);  

    // length of the previous longest 
    // prefix-suffix
    int len = 0;  
    int i = 1;

    while (i < n) {
        if (s[i] == s[len]) {
            lps[i] = ++len;
            i++;
        } 
        else{
            if (len != 0) {
                // Fall back in the LPS array
                len = lps[len - 1];  
            } 
            else{
                lps[i] = 0;
                i++;
            }
        }
    }

    // lps[n - 1] holds the result for 
    // the entire string
    return lps[n - 1];
}

int main() {
    string s = "ababab";
    cout << getLPSLength(s) << endl;
    return 0;
}


