Output4Time Complexity: O(n) we iterate through the string once using the i pointer, and in the worst case, each character is processed at most twice (once when matched, once when falling back via len = lps[len - 1]).Auxiliary Space: O(n)[Efficient Approach] Double Hash Prefix-Suffix Check - O(n) Time and O(1) SpaceThe idea is to use double rolling hash to compute and compare the hash values of the prefix and suffix of every possible length from 1 to n-1.We update prefix and suffix hashes in each iteration and check if they match. If both hashes match, we update the result with the current length. Using two moduli reduces the risk of hash collisions and ensures correctness.Step by Step Implementation:Initialize constants - two bases (base1, base2) and two mod values (mod1, mod2) for double hashing.Initialize:-> Prefix powers p1, p2 as 1.-> Hash arrays: hash1 and hash2 (both of size 2) to store prefix and suffix hashes.-> ans to store the final result.Loop through the string from index 0 to n-2:-> Update hash1[0] and hash1[1] by adding current character's weighted value to the prefix hash.-> Update hash2[0] and hash2[1] by appending character from the end to the suffix hash.If both pairs match, update ans = i + 1.Multiply p1 with base1, and p2 with base2 under mod.Return ans as the length of the longest prefix which is also a suffix.
            C++

    #include <iostream>
#include <vector>
#include <string>
using namespace std;

int getLPSLength(string &s) {

    int base1 = 31, base2 = 37;
    int mod1 = 1e9 + 7, mod2 = 1e9 + 9;

    int p1 = 1, p2 = 1;
    int n = s.size();

    // hash1 for prefix, hash2 for suffix
    vector<int> hash1(2, 0), hash2(2, 0);
    int ans = 0;

    for (int i = 0; i < n - 1; i++) {

        // Update prefix hashes
        hash1[0] = (hash1[0] + 1LL * 
                    (s[i] - 'a' + 1) * p1 % mod1) % mod1;
        hash1[1] = (hash1[1] + 1LL * 
                    (s[i] - 'a' + 1) * p2 % mod2) % mod2;

        // Update suffix hashes
        hash2[0] = (1LL * hash2[0] * base1 % mod1 + 
                        (s[n - i - 1] - 'a' + 1)) % mod1;
        hash2[1] = (1LL * hash2[1] * base2 % mod2 + 
                        (s[n - i - 1] - 'a' + 1)) % mod2;

        // Check if both hash pairs match
        if (hash1 == hash2) {
            ans = i + 1;
        }

        // Update powers
        p1 = 1LL * p1 * base1 % mod1;
        p2 = 1LL * p2 * base2 % mod2;
    }

    return ans;
}

int main() {
    string s = "ababab";
    cout << getLPSLength(s) << endl;
    return 0;
}


